def _ends_with_newline(handle: Any) -> bool:
 """True when the file is empty or already ends in a newline."""
 try:
 handle.seek(0, 2)
 if handle.tell() == 0:
 return True
 handle.seek(handle.tell() - 1)
 return handle.read(1) == "\n"
 except (OSError, ValueError):
 return True


