 r"<arg_key>(.*?)</arg_key>\s*<arg_value>(.*?)</arg_value>",
 re.DOTALL | re.IGNORECASE,
)


def _extract_xml_tool_calls(raw: str) -> List[ToolCall]:
 """Extract tool calls formatted in <tool_call>...<arg_key>..</arg_value> markup."""
