async def _httpx_transport(url: str, headers: Dict[str, str],
 payload: Optional[Dict[str, Any]],
 timeout_s: float) -> Tuple[int, Dict[str, Any]]:
 import httpx
 async with httpx.AsyncClient(timeout=timeout_s) as client:
