def _bin_pack_by_bytes(reg_tables, size_lookup, target_bytes, max_chunks):
 """Greedy first-fit-decreasing bin-pack. Returns None if size_lookup is empty."""
 if not size_lookup:
 return None

 known = [v for v in size_lookup.values() if v > 0]
 avg = (sum(known) // len(known)) if known else 0

 def sz(t):
 return size_lookup.get((t["catalog"], t["schema"], t["table_name"]), avg)

 sorted_tables = sorted(reg_tables, key=lambda t: -sz(t))

 chunks, cur, cur_bytes = [], [], 0
 for t in sorted_tables:
 s = sz(t)
 if s >= target_bytes:
 if cur:
 chunks.append(cur); cur, cur_bytes = [], 0
 chunks.append([t])
 continue
 if cur and cur_bytes + s > target_bytes:
 chunks.append(cur); cur, cur_bytes = [], 0
 cur.append(t); cur_bytes += s
 if cur:
 chunks.append(cur)

 while len(chunks) > max_chunks:
 chunks.sort(key=lambda c: sum(sz(t) for t in c))
 chunks[0].extend(chunks[1])
 chunks.pop(1)

 return chunks


def _safe_set_task_value(key, descriptors, log):
 """Set a taskValue, guarding against the ~48KB Databricks payload limit.

 If the JSON is too large, merge the smallest chunks until it fits.
 If it still won't fit after maximum merging, skip with a warning
 (the downstream job reads from dr_clone_tasks table instead).
 """
 payload = json.dumps(descriptors)
 byte_size = len(payload.encode("utf-8"))
 if byte_size <= TASK_VALUE_MAX_BYTES:
 try:
 dbutils.jobs.taskValues.set(key=key, value=payload)
 return
 except Exception as _exc: # noqa: BLE001
 log.warning(
 "taskValue '%s' rejected by API (%d bytes) -- will try merging. Error: %s",
 key, byte_size, str(_exc)[:200],
