 key, byte_size, len(descriptors),
 )
 # Merge pairs from the end until the payload fits.
 merged = list(descriptors)
 while len(json.dumps(merged).encode("utf-8")) > TASK_VALUE_MAX_BYTES and len(merged) > 1:
 merged[-2]["row_count"] += merged[-1]["row_count"]
 merged.pop()

