def _walk_tree(dbutils, root: str) -> Tuple[Optional[List[Tuple[str, int]]], Optional[str]]:
 """Recursive ``dbutils.fs.ls`` walk -> (sorted [(path, size)], error|None).

 Serial, not threaded -- some serverless/Spark Connect runtimes bind
 ``dbutils`` to the main thread.
 """
 files: List[Tuple[str, int]] = []
 stack = [root]
 try:
 while stack:
 current = stack.pop()
 for e in dbutils.fs.ls(current):
 if e.name.endswith("/"):
 stack.append(e.path)
 else:
 files.append((e.path, int(e.size)))
 return sorted(files), None
 except Exception as exc: # noqa: BLE001
 return None, str(exc)[:300]


def file_count_bytes(
 files: Optional[List[Tuple[str, int]]], err: Optional[str],
) -> str:
 """DC-19 -- source file count + total bytes, from an already-walked tree."""
 if files is None:
 return f"ERROR: {err or 'walk failed'}"
 return f"files={len(files)} bytes={sum(sz for _, sz in files)}"


def file_listing(
 files: Optional[List[Tuple[str, int]]], err: Optional[str], root_path: str,
) -> str:
 """DC-19 companion -- every file's path (relative to the volume root) and
 size as a JSON array, from the SAME walk. Same convention as the target
 side so the two listings diff directly."""
 if files is None:
 return f"ERROR: {err or 'walk failed'}"
 root = (root_path or "").rstrip("/")
 entries = []
 for path, size in files:
 rel = (
 path[len(root):].lstrip("/")
 if root and path.startswith(root)
 else path.rsplit("/", 1)[-1]
 )
 entries.append({"path": rel, "size": size})
 return json.dumps(entries)


def files_readable_integrity(
 files: Optional[List[Tuple[str, int]]], err: Optional[str],
) -> str:
 """DC-20 -- is the volume ACCESSIBLE: ``"true"`` / ``"false"``.

 Decided purely by whether the recursive listing succeeded; deliberately
 reads no file contents, matching the target side.
 """
 return "true" if files is not None else "false"


