class StorageAccountMapper:
 """Manages the dr_storage_account_mapping Delta table.

 Resolves source -> target storage accounts dynamically based on
 clone direction (EAST_TO_SOUTHEAST or SOUTHEAST_TO_EAST).
 """

 _ABFSS_PATTERN = re.compile(
 r"abfss://([^@]+)@([^.]+)\.dfs\.core\.windows\.net(.*)"
 )

 def __init__(self, config: DeepCloneConfig, spark) -> None:
 self.config = config
 self.spark = spark
 self._east_to_se: Optional[Dict[str, str]] = None
 self._se_to_east: Optional[Dict[str, str]] = None

 def bootstrap(self) -> None:
 """Create the storage mapping table if it doesn't exist, and seed defaults."""
 loc = self.config.get_metadata_table_location(
 DeepCloneConfig.storage_mapping_table_name
 )
 if not self._table_exists(self.spark, self.config.storage_mapping_table):
 try:
 self.spark.sql(f"""
 CREATE TABLE IF NOT EXISTS {self.config.storage_mapping_table} (
 layer STRING,
 southeast_storage_account STRING NOT NULL,
 east_storage_account STRING NOT NULL
 )
 USING DELTA LOCATION '{loc}'
 """)
 except Exception as exc:
 raise RuntimeError(
 f"Cannot create {self.config.storage_mapping_table}. "
 f"Run setup_metadata_tables notebook first."
 ) from exc

 count = self.spark.sql(
 f"SELECT COUNT(*) AS cnt FROM {self.config.storage_mapping_table}"
 ).collect()[0]["cnt"]
 if count == 0 and self.config.storage_mappings:
 for mapping in self.config.storage_mappings:
 layer = mapping["layer"].replace("'", "''")
 se_acct = mapping["southeast_storage_account"].replace("'", "''")
 east_acct = mapping["east_storage_account"].replace("'", "''")
 self.spark.sql(f"""
 INSERT INTO {self.config.storage_mapping_table}
 VALUES ('{layer}', '{se_acct}', '{east_acct}')
 """)
 logger.info(
 "Seeded %d storage account mappings from config",
 len(self.config.storage_mappings),
 )

 logger.info("StorageAccountMapper.bootstrap() -- table ready at %s", loc)

 @staticmethod
 def _table_exists(spark, fqn: str) -> bool:
 """Check if a Delta table exists by attempting DESCRIBE TABLE."""
 try:
 spark.sql(f"DESCRIBE TABLE {fqn}")
 return True
 except Exception: # noqa: BLE001 -- Spark AnalysisException is not importable in all envs
 logger.debug("Table %s does not exist or is inaccessible", fqn)
 return False

 def load_mappings(self) -> Tuple[Dict[str, str], Dict[str, str]]:
 """Load all mappings from the storage mapping table."""
 rows = self.spark.table(self.config.storage_mapping_table).collect()
 self._east_to_se = {
 r.east_storage_account: r.southeast_storage_account for r in rows
 }
 self._se_to_east = {
 r.southeast_storage_account: r.east_storage_account for r in rows
 }
 logger.info("StorageAccountMapper: loaded %d mappings", len(rows))
 return self._east_to_se, self._se_to_east

 def get_target_storage_account(self, source_storage_account: str) -> Optional[str]:
 """Resolve the target storage account for a given source account."""
 if self._east_to_se is None:
 self.load_mappings()
 if self.config.clone_direction == "EAST_TO_SOUTHEAST":
 return self._east_to_se.get(source_storage_account)
 return self._se_to_east.get(source_storage_account)

