 raise ValueError(f"{name} must be non-negative, got {ver}")
 return ver

 def _validate_date(self, value: str, name: str) -> None:
 """Validate a date key: a full date (yyyy-MM-dd) or a yyyymm month key.

 yyyymm supports tables partitioned by an integer year-month column;
 the restore strategies pick the right (quoted vs numeric) predicate
 from the column type at run time.
 """
 if not (self._DATE_PATTERN.match(value) or self._MONTH_PATTERN.match(value)):
 raise ValueError(
 f"{name} must be in yyyy-MM-dd or yyyymm format, got '{value}'"
 )

 def _validate_column_name(self, value: str, name: str) -> None:
 """Validate that a column name is a safe SQL identifier."""
 if not self._IDENTIFIER_PATTERN.match(value):
 raise ValueError(
 f"{name} must be a valid column identifier, got '{value}'"
 )

