 def _append_log_row(self, row: Tuple) -> None:
 """Thread-safe append to pending log buffer."""
 with self._log_lock:
 self._pending_log_rows.append(row)

 def _flush_pending_logs(self, force: bool = False) -> int:
 """Write pending log rows to Delta if buffer exceeds batch size.

 Args:
 force: If True, flush regardless of buffer size (for final flush).

 Returns:
 Number of rows flushed (0 if nothing to flush).
 """
 with self._log_lock:
 if not self._pending_log_rows:
 return 0
 if not force and len(self._pending_log_rows) < _LOG_FLUSH_BATCH_SIZE:
 return 0
 batch = list(self._pending_log_rows)
 self._pending_log_rows.clear()

 self._write_log_batch(batch)
 self._flushed_count += len(batch)
 return len(batch)

 def _write_log_batch(self, rows: List[Tuple]) -> None:
 """Write a batch of log rows to Delta with retry."""
 if not rows:
 return
 log_df = self.spark.createDataFrame(rows, schema=self.REG_LOG_SCHEMA)
 for attempt in range(_max_retries + 1):
 try:
 (
 log_df.write.format("delta")
 .option("mergeSchema", "true")
 .mode("append")
 .saveAsTable(self.config.registration_log_table)
 )
 return
 except Exception as exc:
 if "DELTA_CONCURRENT_APPEND" in str(exc) and attempt < _max_retries:
 wait_sec = 2 ** attempt + random.uniform(0, 1)
 logger.warning(
 "[log-flush retry %d/%d] concurrent conflict, "
 "retrying in %.1fs ...",
 attempt + 1, _max_retries, wait_sec,
 )
 time.sleep(wait_sec)
 else:
 raise

 def log_operation(
 self, run_id: str, op_type: str, catalog: str, schema: str,
 table: str, location: str, status: str, error: Optional[str],
 ts: datetime,
 ) -> None:
 """Record an operation (schema/ext-loc/table) to the audit buffer."""
 self._append_log_row(
 (run_id, op_type, catalog, schema, table, location, status, error, ts)
 )

 def _create_delta_pointer(
 self, catalog: str, schema: str, table: str, location: str,
 props: Optional[Dict[str, str]] = None,
 ) -> None:
 """``CREATE TABLE IF NOT EXISTS ... USING DELTA LOCATION`` for an existing
 Delta path. When *props* is given they are emitted as ``TBLPROPERTIES`` so
 the specified property set exactly matches the existing log (required by
 Delta when the runtime would otherwise inject differing defaults).
 """
 tbl = f"`{catalog}`.`{schema}`.`{table}`"
 if props:
 pairs = ", ".join(
 f"'{k.replace(chr(39), chr(39) * 2)}' = "
 f"'{str(v).replace(chr(39), chr(39) * 2)}'"
 for k, v in props.items()
 )
 self.spark.sql(
 f"CREATE TABLE IF NOT EXISTS {tbl} USING DELTA "
 f"LOCATION '{location}' TBLPROPERTIES ({pairs})"
 )
