import logging
from dataclasses import dataclass, field
from typing import Dict, List, Optional

logger = logging.getLogger(__name__)

_VALID_CLONE_TYPES = {"SYNC", "FULL"}
_VALID_FAILOVER_TYPES = {
 "CATALOG", "SCHEMA", "TABLE",
