@dataclass
class GrantScope:
 """Parsed scope. ``scope_type`` in {CATALOG, SCHEMA, TABLE, ALL}."""
 scope_type: str
 catalog: str = ""
 schema: str = ""
 table: str = ""

 @classmethod
 def parse(cls, scope_type: str, scope_value: str) -> "GrantScope":
 st = (scope_type or "").strip().upper()
 sv = (scope_value or "").strip()
 if st not in VALID_SCOPES:
 raise ValueError(
 f"scope_type must be one of {sorted(VALID_SCOPES)}, got {st!r}"
 )
 if st == "ALL":
 return cls(scope_type="ALL")
 parts = [p for p in sv.split(".") if p]
 if st == "CATALOG":
 if len(parts) != 1:
 raise ValueError("CATALOG scope_value must be 'catalog'")
 return cls("CATALOG", catalog=parts[0])
 if st == "SCHEMA":
 if len(parts) != 2:
 raise ValueError("SCHEMA scope_value must be 'catalog.schema'")
 return cls("SCHEMA", catalog=parts[0], schema=parts[1])
 if st == "TABLE":
 if len(parts) != 3:
 raise ValueError("TABLE scope_value must be 'catalog.schema.table'")
 return cls("TABLE", catalog=parts[0], schema=parts[1], table=parts[2])
 raise ValueError(f"unhandled scope_type {st!r}")


