class GrantExtractor:
 """Reads catalog/schema/table privileges from the SOURCE UC and persists
 them to ``dr_clone_grants``.

 All reads hit ``<catalog>.information_schema.*_privileges`` views (bulk,
 metadata-only). Owner columns are captured best-effort for reference.
 """

 def __init__(self, spark, grant_table_fqn: str) -> None:
 self.spark = spark
 self.fqn = grant_table_fqn

 # -- public API --------------------------------------------------------

 def extract_and_persist(
 self, *, scope_type: str, scope_value: str,
 source_region: str, run_id: str,
 ) -> Dict[str, int]:
 """Extract grants for the scope and overwrite the scope's rows in
 ``dr_clone_grants``. Returns counts per securable level."""
 region = (source_region or "").strip().upper()
 if region not in VALID_REGIONS:
 raise ValueError(
 f"source_region must be one of {sorted(VALID_REGIONS)}, got {region!r}"
 )
 scope = GrantScope.parse(scope_type, scope_value)

 catalogs = self._resolve_catalogs(scope)
 rows: List[Tuple] = []
 now = datetime.now(timezone.utc).replace(tzinfo=None)
 owners = self._capture_owners(scope, catalogs)

 for cat in catalogs:
 try:
 rows.extend(
 self._extract_catalog(scope, cat, region, run_id, now, owners)
 )
 except Exception:
 err = traceback.format_exc(limit=3)
 logger.warning("grant extract failed for catalog %s: %s",
 cat, err[:300])
 rows.append((
 run_id, region, "CATALOG", cat, None, None,
 "_EXTRACT_FAILED_", "_NONE_", "NO",
 owners.get(("CATALOG", cat, None, None), ""),
 now, "FAILED",
 ))

 self._overwrite_scope(scope, region, rows)

 counts = {"CATALOG": 0, "SCHEMA": 0, "TABLE": 0, "total": len(rows)}
 for r in rows:
 if r[10] == "SUCCESS" or r[6] != "_EXTRACT_FAILED_":
 counts[r[2]] = counts.get(r[2], 0) + 1
 logger.info("grant extract: scope=%s region=%s rows=%d (%s)",
 scope.scope_type, region, len(rows), counts)
 return counts

 # -- internals ---------------------------------------------------------

 def _resolve_catalogs(self, scope: GrantScope) -> List[str]:
 if scope.scope_type == "ALL":
 try:
 rows = self.spark.sql("SHOW CATALOGS").collect()
 # Exclude system / sample catalogs that aren't cloned.
 skip = {"system", "samples", "__databricks_internal"}
 return [r[0] for r in rows if r[0] and r[0] not in skip]
 except Exception: # noqa: BLE001
 logger.warning("SHOW CATALOGS failed -- no catalogs resolved")
 return []
 return [scope.catalog]

 def _capture_owners(
 self, scope: GrantScope, catalogs: Sequence[str],
 ) -> Dict[Tuple, str]:
 """Best-effort owner lookup keyed by (level, cat, schema, table).

 Scoped to the requested securable: a SCHEMA scope only reads that
 schema (and its tables); a TABLE scope only reads that one table. This
 avoids scanning the whole catalog's information_schema for a narrow
 scope. CATALOG / ALL still read every schema/table in the catalog.
 """
 # Build scope predicates once (literals are escaped). Empty = no filter.
 sch_pred = "" # for information_schema.schemata (schema_name)
 sch_tbl_pred = "" # for information_schema.tables (table_schema[/name])
 if scope.scope_type == "SCHEMA":
 sch_pred = f" WHERE schema_name = '{_esc(scope.schema)}'"
 sch_tbl_pred = f" WHERE table_schema = '{_esc(scope.schema)}'"
 elif scope.scope_type == "TABLE":
 sch_pred = f" WHERE schema_name = '{_esc(scope.schema)}'"
 sch_tbl_pred = (
 f" WHERE table_schema = '{_esc(scope.schema)}'"
 f" AND table_name = '{_esc(scope.table)}'"
 )

 owners: Dict[Tuple, str] = {}
 for cat in catalogs:
 try:
 for r in self.spark.sql(
 f"SELECT schema_name, schema_owner "
 f"FROM {_q(cat)}.information_schema.schemata{sch_pred}"
 ).collect():
