"""Structured log formatters — shared between Deep Clone and Failover DR.

Mirrors bdp.core.logging.log_formatter from dab-framework.
"""

import json
import time
import logging
import logging.handlers

from datetime import datetime
from collections import OrderedDict

from shared.constants import default_timezone, json_field_size_limit

try:
 import pytz
except ImportError:
 pytz = None


class JSONEncoderLogging(json.JSONEncoder):
 """Provides standard encoding to JSON for some common Python datatypes."""

 def default(self, o, timezone: str = default_timezone):
 if isinstance(o, set):
 return tuple(o)
 elif isinstance(o, datetime):
 if pytz:
 return o.astimezone(pytz.timezone(timezone)).isoformat()
 return o.isoformat()

 try:
 return super().default(o)
 except TypeError:
 return str(o)


class LogFormatStructured(logging.Formatter):
 """Abstract base for structured log formatters."""

 def __init__(self, timezone: str = default_timezone):
 super().__init__()
 if pytz:
 self.timezone = pytz.timezone(timezone)
 else:
 self.timezone = None

 self.excluded_keys = [
 "name", "msg", "args", "levelno", "pathname", "filename",
 "module", "lineno", "funcName", "created", "msecs",
 "relativeCreated", "thread", "threadName", "processName",
 "process", "levelname", "exc_info", "exc_text", "stack_info",
 "RunId", "Operation",
 ]

 def format_structured_msg(self, header, structured_msg):
 raise NotImplementedError("Override this method")

 def format_time(self, dt: datetime):
 return dt.isoformat()

 def format(self, record):
 if self.timezone:
 ts = self.format_time(datetime.fromtimestamp(record.created, self.timezone))
 else:
 ts = self.format_time(datetime.fromtimestamp(record.created))

 # Use getMessage() so printf-style args ('log.error("x=%s", y)') get
 # substituted. Previously we used record.msg (the raw format string)
 # and "%s" placeholders leaked through to the log output.
 header = [
 ("TimeGenerated", ts),
 ("Logger", record.name),
 ("RunId", record.__dict__.get("RunId")),
 ("Level", record.levelname),
 ("Operation", record.__dict__.get("Operation")),
 ("Message", record.getMessage()),
 ]

 if record.exc_info:
 header += [("Exception", self.formatException(record.exc_info))]

 structured_msg = [
 (k, v)
 for k, v in record.__dict__.items()
 if k not in self.excluded_keys and v is not None
 ]

 return self.format_structured_msg(header, structured_msg)


class LogFormatStructuredLogAnalytics(LogFormatStructured):
 """Output a JSON record suitable for ingestion by Azure Log Analytics."""

 def __init__(self, timezone: str = default_timezone):
 super().__init__(timezone)
 self.encoder = JSONEncoderLogging()

 def format_time(self, dt: datetime):
 return dt.isoformat()

 def format_structured_msg(self, header, structured_msg):
 output = [(k, str(v)) for k, v in header if v is not None]

 if structured_msg:
 output += [("Extra", self.encoder.encode(OrderedDict(structured_msg)))]

 for idx, (k, v) in enumerate(output):
 if len(bytes(self.encoder.encode(v), "utf-8")) > json_field_size_limit:
 output[idx] = (k, v[0 : json_field_size_limit - 15] + "... <truncated>")

 return self.encoder.encode(OrderedDict(output))


class LogFormatStructuredDelimited(LogFormatStructured):
 """Human-readable space-delimited format.

 Example: ``2025-01-01 11:58:47 hello INFO 1234 [my operation] Hello``
 """

 def __init__(self, timezone: str = default_timezone):
 super().__init__(timezone)

 def format_time(self, dt: datetime):
 return dt.strftime("%Y-%m-%d %H:%M:%S")

 def format_structured_msg(self, header, structured_msg):
 header = [
 (k, "[" + (v or "main") + "]") if k == "Operation" else (k, v)
 for k, v in header
 ]
 header_str = " ".join([str(v) for k, v in header])

 if structured_msg:
 return (
 header_str
 + " "
 + " ".join([k + " = " + str(v) for k, v in structured_msg])
 )
 return header_str


