 def _load_target_schema_tags(
 self, wanted: Sequence[Tuple[str, str]],
 ) -> Tuple[
 Dict[Tuple[str, str], Optional[set]],
 Dict[Tuple[str, str], Optional[str]],
 ]:
 """Bulk-read the tag names + comment CURRENTLY on the target SCHEMAS
 (one pair of queries per catalog) so schema tags / comments removed on
 the source can be UNSET / cleared. ``None`` for a catalog whose read
 failed (fail-safe: unknown -> remove nothing)."""
 tags_out: Dict[Tuple[str, str], Optional[set]] = {}
 cmt_out: Dict[Tuple[str, str], Optional[str]] = {}
 if not wanted:
 return tags_out, cmt_out
 by_catalog: Dict[str, List[str]] = {}
 for c, s in wanted:
 by_catalog.setdefault(c, []).append(s)
 for catalog, schemas in by_catalog.items():
 distinct = sorted(set(schemas))
 sch_in = ", ".join(f"'{escape_sql(s)}'" for s in distinct)
 local = {(catalog, s): set() for s in distinct}
 local_cmt = {(catalog, s): "" for s in distinct}
 try:
 for r in self.spark.sql(
 f"""
 SELECT schema_name, tag_name
 FROM `{catalog}`.information_schema.schema_tags
 WHERE schema_name IN ({sch_in})
 """
 ).collect():
 kk = (catalog, r.schema_name)
 if kk in local:
 local[kk].add(r.tag_name)
 tags_out.update(local)
 except Exception as exc: # noqa: BLE001
 logger.info(
 "[schema-md unset] target schema_tags read failed for %s: %s",
 catalog, str(exc)[:200],
 )
 for kk in local:
 tags_out[kk] = None
 try:
 for r in self.spark.sql(
 f"""
 SELECT schema_name, COALESCE(comment, '') AS comment
 FROM `{catalog}`.information_schema.schemata
 WHERE schema_name IN ({sch_in})
 """
 ).collect():
 kk = (catalog, r.schema_name)
 if kk in local_cmt:
 local_cmt[kk] = r.comment or ""
 cmt_out.update(local_cmt)
 except Exception as exc: # noqa: BLE001
 logger.info(
 "[schema-md clear] target schema comment read failed for "
 "%s: %s", catalog, str(exc)[:200],
 )
 for kk in local_cmt:
 cmt_out[kk] = None
 return tags_out, cmt_out

