def scope_from_filters(
 target_catalog: str,
 target_schema: str = "",
 target_table: str = "",
) -> List[ViewScopeItem]:
 """Build scope items from the table-register-style filter parameters.

 Mirrors the ``dr_table_registration_job`` convention (``target_catalog`` /
 ``target_schema`` / ``target_table``) so a user picks scope with three
 simple, familiar parameters instead of a dotted string::

 target_catalog only -> every view in the catalog(s)
 target_catalog + target_schema -> every view in the schema(s)
 target_catalog + target_schema + table -> only those specific views

 Each parameter may be a comma-separated list. Schemas/views apply across
 every listed catalog (cartesian), exactly like picking a catalog then
 narrowing to schemas then to individual objects.
 """
 cats = [c.strip().strip("`").strip() for c in (target_catalog or "").split(",") if c.strip()]
 schemas = [s.strip().strip("`").strip() for s in (target_schema or "").split(",") if s.strip()]
 views = [v.strip().strip("`").strip() for v in (target_table or "").split(",") if v.strip()]

 if not cats:
 raise ValueError(
 "target_catalog is required (one or more comma-separated catalogs)."
 )
 if views and not schemas:
 raise ValueError(
 "target_table requires target_schema (a view must name its schema)."
 )

 items: List[ViewScopeItem] = []
 if not schemas: # whole-catalog
 for c in cats:
 items.append(ViewScopeItem("CATALOG", c))
 elif not views: # whole-schema
 for c in cats:
 for s in schemas:
 items.append(ViewScopeItem("SCHEMA", c, s))
 else: # individual views
 for c in cats:
 for s in schemas:
 for v in views:
 items.append(ViewScopeItem("VIEW", c, s, v))
 return items


