@dataclass
class ViewDefinition:
 """A single extracted view and everything needed to re-create it."""

 catalog: str
 schema: str
 name: str
 view_definition: str
 create_ddl: str = ""
 comment: str = ""
 # Source (Southeast) schema's own storage_root, and the East equivalent
 # (same container + path, storage account swapped via the mapping table).
 # Empty when the schema inherits its location from the catalog.
 source_schema_location: str = ""
 target_schema_location: str = ""
 # UC metadata that CREATE OR REPLACE VIEW does NOT carry; re-applied on the
 # East side after the view is created (grants are handled elsewhere).
 # view_tags -> dict[str, str]
 # column_metadata -> list[{"name", "comment", "tags": dict}]
 # view_properties -> dict[str, str] (internal view.* / delta.* excluded)
 view_tags: dict = field(default_factory=dict)
 column_metadata: list = field(default_factory=list)
