 @property
 def fqn(self) -> str:
 return f"`{self.catalog}`.`{self.schema}`.`{self.name}`"

 @property
 def definition_hash(self) -> str:
 """Hash of the (whitespace-normalized) definition for change detection."""
 return definition_hash(self.view_definition)

 def to_dict(self) -> dict:
 return asdict(self)

 @classmethod
 def from_dict(cls, d: dict) -> "ViewDefinition":
 return cls(
 catalog=d["catalog"],
 schema=d["schema"],
 name=d["name"],
 view_definition=d.get("view_definition", ""),
 create_ddl=d.get("create_ddl", ""),
 comment=d.get("comment", "") or "",
 source_schema_location=d.get("source_schema_location", "") or "",

