 def _fill_create_ddls(self, views: List[ViewDefinition]) -> None:
 """Populate ``create_ddl`` for each view via SHOW CREATE TABLE, in
 parallel (independent per-view round-trips)."""
 if not views:
 return
 workers = min(self.max_workers, len(views))
 if workers <= 1:
 for vd in views:
 vd.create_ddl = self._show_create(vd)
 return
 with ThreadPoolExecutor(max_workers=workers) as pool:
 for vd, ddl in zip(views, pool.map(self._show_create, views)):
 vd.create_ddl = ddl

 def _attach_schema_locations(self, views: List[ViewDefinition]) -> None:
 """Resolve each distinct schema's source + East location once and stamp
 it onto every view in that schema (denormalized, like the table register
 stores ``east_schema_location`` on each table row)."""
 cache: dict = {}
 for vd in views:
 key = (vd.catalog, vd.schema)
 if key not in cache:
 cache[key] = self.schema_resolver.resolve(vd.catalog, vd.schema)
 src, tgt = cache[key]
 vd.source_schema_location = src or ""
 vd.target_schema_location = tgt or ""
 located = sum(1 for v in views if v.target_schema_location)
 self.log.info(
 "resolved schema locations: %d schema(s); %d view(s) carry an East "
 "managed location (rest inherit from the catalog)",
 len(cache), located,
 )

 # -- UC metadata capture (tags / column comments / properties) ----------
 # CREATE OR REPLACE VIEW carries only the SQL + the view comment. Tags,
 # column comments/tags and (user) properties live in the source metastore
 # and must be captured here and re-applied on East. Mirrors the table
 # register's dr_clone_table_metadata extraction. Grants are handled
 # elsewhere. Internal view.* / delta.* / spark.* properties are excluded.
 _RESERVED_PROPERTY_PREFIXES = ("view.", "delta.", "spark.")
 _RESERVED_PROPERTY_KEYS = {"transient_lastddltime"}

 def _attach_view_metadata(self, views: List[ViewDefinition]) -> None:
 """Capture view tags, column comments/tags and user properties for every
 extracted view. Bulk per-catalog reads for tags/columns (one set of
 information_schema queries per catalog); per-view SHOW TBLPROPERTIES for
 properties. Best-effort: a failure leaves that slice empty, never raises.
 """
 by_catalog: dict = {}
 for vd in views:
 by_catalog.setdefault(vd.catalog, []).append(vd)

 for cat, vlist in by_catalog.items():
 try:
 self._attach_catalog_view_metadata(cat, vlist)
 except Exception as exc: # noqa: BLE001 - decorative, never fatal
 self.log.warning(
 "view-metadata capture failed for catalog %s: %s",
 cat, str(exc)[:300],
 )

 # Properties are per-object (no information_schema view exists for them).
 if views:
 workers = min(self.max_workers, len(views))
 if workers <= 1:
 for vd in views:
 vd.view_properties = self._show_view_properties(vd)
 else:
 with ThreadPoolExecutor(max_workers=workers) as pool:
 for vd, props in zip(
 views, pool.map(self._show_view_properties, views)
 ):
 vd.view_properties = props

 with_tags = sum(1 for v in views if v.view_tags)
 with_colmeta = sum(1 for v in views if v.column_metadata)
 with_props = sum(1 for v in views if v.view_properties)
 self.log.info(
 "view metadata captured: %d w/ view-tags, %d w/ column-metadata, "
 "%d w/ properties (of %d views)",
 with_tags, with_colmeta, with_props, len(views),
 )

 def _attach_catalog_view_metadata(
 self, catalog: str, vlist: List[ViewDefinition],
 ) -> None:
 """Bulk-read tags + column comments/tags for one catalog's views.

 Scoped to only the schemas these views live in -- the information_schema
 tables (especially ``columns``) are catalog-wide, so an unfiltered read
 scans every table in the catalog. Restricting to the in-scope schemas
 turns a multi-minute catalog scan into a small, targeted read.
 """
 meta_by_key = {(v.schema, v.name): v for v

"""Bulk-read tags + column comments/tags for one catalog's views.

 Scoped to only the schemas these views live in -- the information_schema
 tables (especially ``columns``) are catalog-wide, so an unfiltered read
 scans every table in the catalog. Restricting to the in-scope schemas
 turns a multi-minute catalog scan into a small, targeted read.
 """
 meta_by_key = {(v.schema, v.name): v for v in vlist}
 c = self._ident(catalog)
 schemas = {v.schema for v in vlist}
 in_list = _sql_in_list(schemas)

 # View tags (information_schema.table_tags covers views too).
 try:
 where = f"WHERE schema_name IN ({in_list})" if in_list else ""
 for r in self.spark.sql(f"""
 SELECT schema_name, table_name, tag_name, tag_value
 FROM {c}.information_schema.table_tags
 {where}
 """).collect():
 vd = meta_by_key.get((r["schema_name"], r["table_name"]))
 if vd is not None:
 vd.view_tags[r["tag_name"]] = r["tag_value"] or ""
 except Exception as exc: # noqa: BLE001
 self.log.debug("table_tags read failed for %s: %s", catalog, str(exc)[:200])

 # Column comments + ordinal position.
 cols_by_key: dict = {k: [] for k in meta_by_key}
 col_idx: dict = {}
 try:
 where = f"WHERE table_schema IN ({in_list})" if in_list else ""
 for r in self.spark.sql(f"""
 SELECT table_schema, table_name, column_name, ordinal_position,
 COALESCE(comment, '') AS comment
 FROM {c}.information_schema.columns
 {where}
 ORDER BY table_schema, table_name, ordinal_position
 """).collect():
 key = (r["table_schema"], r["table_name"])
 if key in cols_by_key:
 cols_by_key[key].append(
 {"name": r["column_name"], "comment": r["comment"], "tags": {}}
 )
 except Exception as exc: # noqa: BLE001
 self.log.debug("columns read failed for %s: %s", catalog, str(exc)[:200])

 col_idx = {
 key: {c2["name"]: i for i, c2 in enumerate(cols)}
 for key, cols in cols_by_key.items()
 }

 # Column tags.
 try:
 where = f"WHERE schema_name IN ({in_list})" if in_list else ""
 for r in self.spark.sql(f"""
 SELECT schema_name, table_name, column_name, tag_name, tag_value
 FROM {c}.information_schema.column_tags
 {where}
 """).collect():
 key = (r["schema_name"], r["table_name"])
 cols = cols_by_key.get(key)
 if not cols:
 continue
 i = col_idx[key].get(r["column_name"])
 if i is not None:
 cols[i]["tags"][r["tag_name"]] = r["tag_value"] or ""
 except Exception as exc: # noqa: BLE001
 self.log.debug("column_tags read failed for %s: %s", catalog, str(exc)[:200])

 # Keep only columns that actually carry a comment or tags.
 for key, vd in meta_by_key.items():
 vd.column_metadata = [
 col for col in cols_by_key.get(key, [])
 if col.get("comment") or col.get("tags")
 ]

 def _show_view_properties(self, vd: ViewDefinition) -> dict:
 """Return user-defined view properties (internal view.* / delta.* /
 spark.* and transient_lastDdlTime excluded)."""
 props: dict = {}
 try:
 rows = self.spark.sql(f"SHOW TBLPROPERTIES {vd.fqn}").collect()
 except Exception as exc: # noqa: BLE001
 self.log.debug("SHOW TBLPROPERTIES failed for %s: %s", vd.fqn, str(exc)[:200])
 return props
 for r in rows:
 key = (r["key"] if "key" in r else r[0]) or ""
 val = (r["value"] if "value" in r else r[1]) or ""
 k = key.strip()
 if not k:
 continue
 kl = k.lower()
 if kl in self._RESERVED_PROPERTY_KEYS:
 continue
 if any(kl.startswith(p) for p in self._RESERVED_PROPERTY_PREFIXES):
 continue
 props[k] = val
 return props

