 def write_schema_results(
 self, run_id: str, results: List["SchemaCreateResult"],
 ) -> int:
 """Append one audit row per schema-creation outcome."""
 if not results:
 return 0
 now = datetime.now(timezone.utc)
 rows = []
 for r in results:
 registered = "FAIL" if r.status in ("FAILED", "ALTER_FAILED") else "SUCCESS"
 detail = r.status + (f" -> {r.location}" if r.location else "")
 rows.append((
 run_id, "SCHEMA_CREATE", "SCHEMA", None,
