@pytest.mark.unit
class TestBootstrap:

 def test_bootstrap_ensures_three_tables(self, mgr, spark):
 # bootstrap() now provisions >=3 metadata tables (status, log, config,
 # clone_tasks, table_metadata). Using an explicit side_effect list is
 # fragile because the exact count evolves with schema additions; a
 # dispatch callable that raises on every DESCRIBE and returns MagicMock
 # otherwise reliably drives all tables through the CREATE branch.
 def _fx(sql):
 s = sql.strip().upper()
 if s.startswith("DESCRIBE TABLE") or s.startswith("DESCRIBE DETAIL"):
 raise Exception("not found")
 return MagicMock()
 spark.sql.side_effect = _fx

 mgr.bootstrap()
 calls = [c[0][0] for c in spark.sql.call_args_list]
 create_calls = [c for c in calls if "CREATE TABLE" in c]
 # At least the original three (status, log, config); more may be added
 # by future schema evolution and that's fine.
 assert len(create_calls) >= 3

 def test_bootstrap_all_exist(self, mgr, spark):
 spark.sql.return_value = MagicMock()
 mgr.bootstrap()
 calls = [c[0][0] for c in spark.sql.call_args_list]
 assert not any("CREATE TABLE" in c for c in calls)


