 def test_backticks_and_whitespace_stripped(self):
 r = parse_inline("TABLE", "`cat`.`sch`.`orders`")
 assert r.targets == [("cat", "sch", "orders")]

 def test_dedupe(self):
 r = parse_inline("CATALOG", "cat1, CAT1, cat1")
 assert r.targets == [("cat1",)]

 def test_empty_raises(self):
 with pytest.raises(ValueError):
 parse_inline("CATALOG", " ")

 @pytest.mark.parametrize("scope,value", [
 ("CATALOG", "cat.sch"), # too many parts
 ("SCHEMA", "cat"), # too few parts
 ("SCHEMA", "cat.sch.tbl"), # too many parts
 ("TABLE", "cat.sch"), # too few parts
 ("TABLE", "cat..tbl"), # empty middle part
 ("CATALOG", "cat,,cat2"), # blank entry collapses -> both still valid, but '' skipped
 ])
 def test_malformed_raises(self, scope, value):
 # cat,,cat2 -> the empty entry is filtered before parsing, so it is NOT
 # malformed; assert only the truly malformed ones raise.
 if value == "cat,,cat2":
 r = parse_inline(scope, value)
 assert r.targets == [("cat",), ("cat2",)]
 else:
 with pytest.raises(ValueError):
 parse_inline(scope, value)


