# RM-facing display names (Title_Case) for the SCENARIO parameter.
SCENARIO_NAMES = {
 1: "Region_Unavailable",
 2: "Storage_Account_Delete",
 3: "Bad_Data_One_Date",
 4: "Bad_Data_Date_Range",
 5: "Table_Truncated",
 6: "Table_Dropped",
 7: "Delta_Log_Deleted",
 8: "Container_Deleted",
}


def resolve_scenario(arg) -> int:
 """Resolve a SCENARIO parameter (number 1-8 or a readable name) to its number."""
 s = str(arg).strip()
 if s.isdigit() and int(s) in SCENARIOS:
 return int(s)
 norm = "".join(ch for ch in s.lower().replace("-", "_").replace(" ", "_")
 if ch.isalnum() or ch == "_")
 for n, nm in SCENARIO_NAMES.items():
 if norm == nm.lower():
 return n
 for n, sc in SCENARIOS.items():
 if norm == sc.key.lower():
 return n
 raise ValueError(
 f"Unknown SCENARIO '{arg}'. Use 1-8 or one of: {list(SCENARIO_NAMES.values())}"
 )

"""Read + measure Delta tables by ABFSS path (SP-OAuth, non-UC style).

All reads are path-based ``delta.`<abfss>``` -- the same way the failover and
recon jobs read -- so masking/UC registration state never affects the numbers.
Used to capture the East baseline before a fault and to compare East vs SE after
recovery.

Parity metrics mirror the recon framework's checks:
 * row_count -> exact ``COUNT(*)``
 * row_hash -> ``SUM(XXHASH64(*))`` bag-equality hash (order-independent)
 * schema -> ordered (name, type) list
"""

from __future__ import annotations

from dataclasses import dataclass
from typing import List, Optional, Tuple


def _ref(path: str) -> str:
 return f"delta.`{path}`"


def path_readable(spark, path: str) -> bool:
 """True if the Delta path can be read (has a valid _delta_log)."""
 try:
 spark.sql(f"DESCRIBE DETAIL {_ref(path)}").collect()
 return True
 except Exception:
 return False


def row_count(spark, path: str, predicate: Optional[str] = None) -> int:
 """Exact row count (full scan). Returns -1 if the path is unreadable."""
 try:
 where = f" WHERE {predicate}" if predicate else ""
 return int(
 spark.sql(f"SELECT COUNT(*) AS c FROM {_ref(path)}{where}").collect()[0]["c"]
 )
 except Exception:
 return -1


def row_hash(spark, path: str, predicate: Optional[str] = None) -> Optional[int]:
 """Order-independent bag hash: SUM(XXHASH64(*)). None if unreadable."""
 try:
 where = f" WHERE {predicate}" if predicate else ""
 v = spark.sql(
 f"SELECT SUM(XXHASH64(*)) AS h FROM {_ref(path)}{where}"
 ).collect()[0]["h"]
 return int(v) if v is not None else 0
 except Exception:
 return None


def delta_version(spark, path: str) -> Optional[int]:
 """Latest committed Delta version, or None if unreadable."""
 try:
 rows = spark.sql(f"DESCRIBE HISTORY {_ref(path)}").select("version").collect()
 return max(int(r["version"]) for r in rows) if rows else None
 except Exception:
 return None


def schema_fields(spark, path: str) -> List[Tuple[str, str]]:
 """Ordered (column_name, type) list. Empty if unreadable."""
 try:
 return [(f.name, f.dataType.simpleString())
 for f in spark.read.format("delta").load(path).schema.fields]
 except Exception:
 return []


@dataclass
class Baseline:
 """Pre-fault snapshot of one table on both sides."""

 fqn: str
 east_location: str
 se_location: str
 east_count: int
 east_version: Optional[int] # used as RESTORE_POINT for VERSION_RESTORE
 se_count: int
 se_version: Optional[int] # used as SOURCE_VERSION for VERSION_RESTORE
 schema: List[Tuple[str, str]]


def capture_baseline(ctx, target) -> Baseline:
 """Snapshot East (pre-fault) and SE for one target table."""
 spark = ctx.spark
 return Baseline(
 fqn=target.fqn,
 east_location=target.east_location,
 se_location=target.se_location,
 east_count=row_count(spark, target.east_location),
 east_version=delta_version(spark, target.east_location),
 se_count=row_count(spark, target.se_location),
 se_version=delta_version(spark, target.se_location),
 schema=schema_fields(spark, target.east_location),
 )


def show_path(ctx, path: str, label: str, log, limit: int = 20) -> None:
 """Log a header and ``display()`` a sample of a Delta path (best-effort).

 A broken / missing path is expected mid-drill (that is the point of the
 simulation), so an unreadable path is logged as a warning, not raised.
 """
 log.info("%s :: %s", label, path)
 try:
 ctx.display(ctx.spark.read.format("delta").load(path).limit(limit))
 except Exception as exc:
 log.warning(" (not readable: %s)", str(exc)[:200])

"""Validation: prove recovered East ≡ SE, and read the failover audit verdict.

Parity mirrors the recon framework's checks (row_count + row_hash + schema) and
is computed inline by path so it works regardless of cluster/UC/masking. The
recon JOB can additionally be run as the production oracle (see jobs.run_recon),
but this inline check is the always-available verdict.

The failover ``run_id`` is generated inside the notebooks as ``failover_%Y%m%d_%H%M%S``
(UTC), not the Databricks job run id, so audit rows are correlated by
(catalog, schema, table) + ``run_id >= drill_start`` — a string/UTC compare that
avoids any session-timezone ambiguity in comparing a Python datetime to the
run_ts TIMESTAMP column.
"""

from __future__ import annotations

import time
from dataclasses import dataclass, field
from datetime import datetime, timedelta
from typing import List, Optional, Tuple

from . import snapshot


@dataclass
class Parity:
 se_count: int
 east_count: int
 se_hash: Optional[int]
 east_hash: Optional[int]
 schema_match: bool

 @property
 def count_match(self) -> bool:
 return self.se_count >= 0 and self.se_count == self.east_count

 @property
 def hash_match(self) -> bool:
 return (self.se_hash is not None and self.east_hash is not None
 and self.se_hash == self.east_hash)

 @property
 def ok(self) -> bool:
 return self.count_match and self.hash_match and self.schema_match


def compare(ctx, target, predicate: Optional[str] = None) -> Parity:
 """Compare East vs SE for one table (optionally scoped to a predicate)."""
 spark = ctx.spark
 se, east = target.se_location, target.east_location
 return Parity(
 se_count=snapshot.row_count(spark, se, predicate),
 east_count=snapshot.row_count(spark, east, predicate),
 se_hash=snapshot.row_hash(spark, se, predicate),
 east_hash=snapshot.row_hash(spark, east, predicate),
 schema_match=snapshot.schema_fields(spark, se) == snapshot.schema_fields(spark, east),
 )


@dataclass
class AuditVerdict:
 found: bool
 status: str = ""
 restore_method: str = ""
 row_count_source: int = 0
 row_count_target: int = 0
 error: str = "" # populated when the audit read itself failed


def _read_audit_df(ctx):
 """Read dr_failover_audit_log via UC FQN, falling back to the ABFSS path."""
 try:
 return ctx.spark.read.table(ctx.failover_audit_table)
 except Exception:
 if ctx.failover_audit_path:
 return ctx.spark.read.format("delta").load(ctx.failover_audit_path)
 raise


def read_failover_audit(
 ctx, target, since_ts: datetime, *, attempts: int = 3, sleep_sec: int = 5
) -> AuditVerdict:
 """Latest audit row for *target* from a failover run started at/after the drill.

 Correlates by ``run_id`` (the notebooks build it as ``failover_%Y%m%d_%H%M%S``
 in UTC) rather than the ``run_ts`` TIMESTAMP — a string/UTC compare avoids
 session-timezone skew. A 2-minute backward margin absorbs inter-cluster clock
 skew; a short retry absorbs Delta commit lag. ``since_ts`` is a naive UTC
 datetime (``datetime.utcnow()``). On read failure the error is surfaced on the
 returned verdict (``error``) instead of being silently swallowed.
 """
 floor = (since_ts - timedelta(minutes=2)).strftime("failover_%Y%m%d_%H%M%S")
 last_err = ""
 for attempt in range(attempts):
 try:
 df = _read_audit_df(ctx)
 rows = (
 df.where(
 (df.table_catalog == target.catalog)
 & (df.table_schema == target.schema)
 & (df.table_name == target.name)
 & (df.run_id >= floor)
 )
 .orderBy(df.run_id.desc())
 .limit(1)
 .collect()
 )
 if rows:
 r = rows[0]
 return AuditVerdict(
 found=True,
 status=r["status"] or "",
 restore_method=r["restore_method"] or "",
 row_count_source=int(r["row_count_source"] or 0),
 row_count_target=int(r["row_count_target"] or 0),
 )
 last_err = "" # read succeeded, row just not visible yet
 except Exception as exc:
 last_err = str(exc)[:300]
 if attempt < attempts - 1:
 time.sleep(sleep_sec)
 return AuditVerdict(found=False, error=last_err)


@dataclass
class TableVerdict:
 fqn: str
 parity: Parity
 audit: AuditVerdict

row_count_source=int(r["row_count_source"] or 0),
 row_count_target=int(r["row_count_target"] or 0),
 )
 last_err = "" # read succeeded, row just not visible yet
 except Exception as exc:
 last_err = str(exc)[:300]
 if attempt < attempts - 1:
 time.sleep(sleep_sec)
 return AuditVerdict(found=False, error=last_err)


@dataclass
class TableVerdict:
 fqn: str
 parity: Parity
 audit: AuditVerdict
 expected_methods: Tuple[str, ...]
 scoped: Optional[Parity] = None # date/range-scoped parity (informational)

 @property
 def method_ok(self) -> bool:
 return (not self.expected_methods) or (
 self.audit.found and self.audit.restore_method in self.expected_methods
 )

 @property
 def audit_ok(self) -> bool:
 return self.audit.found and self.audit.status == "SUCCESS"

 @property
 def passed(self) -> bool:
 return self.parity.ok and self.audit_ok and self.method_ok

