@pytest.mark.unit
class TestComputeMetadataHash:

 def test_stable_for_identical_input(self):
 meta = {
 "table_comment": "customer table",
 "table_tags": {"pii": "true", "domain": "sales"},
 "columns": [
 {"name": "id", "comment": "pk", "tags": {"key": "1"}},
 {"name": "name", "comment": "", "tags": {}},
 ],
 }
 assert compute_metadata_hash(meta) == compute_metadata_hash(dict(meta))

 def test_tag_order_does_not_change_hash(self):
 a = {"table_comment": "", "table_tags": {"a": "1", "b": "2"}, "columns": []}
