 def test_column_order_does_not_change_hash(self):
 a = {
 "table_comment": "", "table_tags": {},
 "columns": [
 {"name": "b", "comment": "x", "tags": {}},
 {"name": "a", "comment": "y", "tags": {}},
 ],
 }
 b = {
 "table_comment": "", "table_tags": {},
 "columns": [
 {"name": "a", "comment": "y", "tags": {}},
 {"name": "b", "comment": "x", "tags": {}},
 ],
 }
